    },
    {
      "section": "5.4.3",
      "label": "[REQ-1-OAD-9812]",
      "text": "The DMS shall define TMT standards for metadata and data storage.",
      "id": "REQ-1-OAD-9812"
    },
    {
      "section": "5.4.3",
      "label": "[REQ-1-OAD-9812]",
      "text": "TMT standards shall use and be compatible with astronomy standards such as FITS and Virtual Observatory services and metadata standards.",
      "id": null
    },
    {
      "section": "5.4.3",
      "label": "[REQ-1-OAD-9367]",
      "text": "The DMS shall implement the proprietary period policy that allows data products and metadata to be private for a specified amount of time that can vary for each TMT partner.",
